style_variants.expression:
/* This page scrolls around the roster; wheel input over its table must reach
   the page when the table viewport has no vertical distance left to scroll. */
.sections :global([data-slot="table-viewport"])

/* The shell's dark gradient is fixed to the viewport. Paint the same gradient
   behind the pinned tabs so rows never show through or create a color seam. */
:global(.dark) .navigation[data-stuck]

branches.expression:
!validation.validate(z.object({ id: z.string().uuid("Selecione uma ocorrência.") }), {
              id: selected,
            })

[count, amountKey, "materialCardFeePct"].some((key) =>
      fieldError(key as keyof SettingsFields, fields[key as keyof SettingsFields]),
    )

localDateTimeEqualsTarget({
        instant: candidate,
        targetMilliseconds: input.targetMilliseconds,
        timeZone: input.timeZone,
      })
